<?php
declare(strict_types=1);use PHPUnit\Framework\TestCase;use Acorn\SafetyHealthcheck\Domain\{RulesEngine,ApplicabilityContext};final class RulesEngineTest extends TestCase{public function test_conditional():void{$p=['jurisdiction'=>'england','employee_band'=>'10_49','sector'=>'office_professional','workplace_types'=>['office'],'premises_responsibility'=>'yes','shared_premises'=>'yes','risk_flags'=>['dse'],'water_system_responsibility'=>'no','maintenance_repair_responsibility'=>'no','building_pre_2000'=>'not_relevant','intrusive_work_planned'=>'no'];$qs=require dirname(__DIR__,2).'/config/questions.php';foreach($qs as &$q)$q['variant_json']='{}';$keys=array_column((new RulesEngine)->applicableQuestions(ApplicabilityContext::fromProfile($p),$qs),'question_key');self::assertContains('D01_DSE',$keys);self::assertContains('F02_FIRE_RA',$keys);self::assertNotContains('C01_COSHH',$keys);}}
